// PROXIMUS | ASSET ALCHEMIST v2.6 — cross-device file transport.
// ZIP reader covers the uncompressed ZIPs generated by this application's makeZip.
import {download,safe} from './core.js';
export function parseStoreZip(bytes,{maxFiles=250,maxBytes=150000000}={}){
 const arr=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);
 if(arr.length>maxBytes+1000000)throw Error('ZIP is larger than the safe portable project limit.');
 const dv=new DataView(arr.buffer,arr.byteOffset,arr.byteLength),decoder=new TextDecoder('utf-8',{fatal:true});
 const entries=[];let pos=0,total=0;
 while(pos+4<=arr.length){
  const sig=dv.getUint32(pos,true);
  if(sig===0x02014b50||sig===0x06054b50)break;
  if(sig!==0x04034b50||pos+30>arr.length)throw Error('Invalid portable project ZIP.');
  if(entries.length>=maxFiles)throw Error('ZIP contains too many files.');
  const flag=dv.getUint16(pos+6,true),method=dv.getUint16(pos+8,true);
  if((flag&8)||method!==0)throw Error('Choose a PROXIMUS exported project ZIP (stored files only).');
  const length=dv.getUint32(pos+18,true),rawLength=dv.getUint32(pos+22,true);
  const nameLength=dv.getUint16(pos+26,true),extraLength=dv.getUint16(pos+28,true);
  if(length!==rawLength||nameLength>256)throw Error('Invalid project ZIP entry.');
  const offset=pos+30+nameLength+extraLength;
  if(offset+length>arr.length)throw Error('Truncated portable project ZIP.');
  const name=decoder.decode(arr.subarray(pos+30,pos+30+nameLength));
  if(!name||name.includes('..')||name.startsWith('/')||name.includes('\\'))throw Error('Unsafe project ZIP entry name.');
  total+=length;if(total>maxBytes)throw Error('Portable project exceeds the safe import limit.');
  entries.push({name,data:arr.slice(offset,offset+length)});
  pos=offset+length;
 }
 if(!entries.length)throw Error('No portable project entries found.');
 return entries;
}
export function mobileFileSupport(){
 return {share:typeof navigator!=='undefined'&&typeof navigator.share==='function'&&typeof File!=='undefined',
  download:true,platform:typeof navigator!=='undefined'&&/iPad|iPhone|iPod/i.test(navigator.userAgent||'')?'iPhone / iPad':'Desktop or other browser'};
}
export async function saveOrShare(blob,name,{preferShare=true}={}){
 if(!(blob instanceof Blob))throw Error('An exported file is required.');
 const filename=safe(name),file=new File([blob],filename,{type:blob.type||'application/octet-stream'});
 if(preferShare&&navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){
  try{
   // This must be called directly from a separate user click to retain mobile activation.
   await navigator.share({files:[file],title:filename});
   return 'shared';
  }catch(e){if(e?.name==='AbortError')return 'cancelled';}
 }
 download(blob,filename);return 'downloaded';
}
export function fileExtension(name){return String(name||'').split('.').pop().toLowerCase();}
